       >>> is_commit("a3bcD445")
       True
       >>> is_commit("xyzzy123")
       False
    """
def is_commit(s: Any) -> object {
    if (len(s) >= 6) {
        try {
            int(s, 16);
            return True;
        } except ValueError {
            ;
        }
    }
    return False;
}

